(36861, 'Joshua 7:21', 'Joshua', 7, 21, 'د هغو شیانو په منځ کې چې مونږ ونیول ما یوه ښایسته بابلۍ چپنه، دوه کیلو ګرامه سپین زر او د سرو زرو سیخ چې وزن یې نیم کیلو ګرام ؤ ولیدل، هغه زما ډېر خوښ شول او ما واخیستل. تاسو به هغه زما د خېمې په منځ کې پیدا کړئ، هغه هلته ښخ دي او د ټولو لاندې سپین زر دي.»', 'د هغو شیانو په منج کې چې مونز ونیول ما یوه شایسته بابلی چپنه، دوه کیلو ګرامه سپین زر او د سرو زرو سیخ چې وزن یې نیم کیلو ګرام و ولیدل، هغه زما دېر خوش شول او ما واخیستل. تاسو به هغه زما د خېمې په منج کې پیدا کری، هغه هلته شخ دی او د تولو لاندې سپین زر دی.»', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Joshua_7_21.mp3', 'https://drive.google.com/uc?id=1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY&export=download', 1761237839, 1761237839),
(36862, 'Joshua 7:22', 'Joshua', 7, 22, 'نو یوشع یو څو کسان ولېږل. هغوی خېمې ته منډه کړه او ویې لیدل چې هغه شیان په رښتیا هلته ښخ وو او د هغو لاندې سپین زر وو.', 'نو یوشع یو چو کسان ولېزل. هغوی خېمې ته منده کره او ویې لیدل چې هغه شیان په رشتیا هلته شخ وو او د هغو لاندې سپین زر وو.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Joshua_7_22.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237839, 1761237839),
(36863, 'Joshua 7:23', 'Joshua', 7, 23, 'هغوی دا شیان د خېمې څخه راوویستل، یوشع او ټولو اسراییلیانو ته یې وروړل او د څښتن په حضور کې یې کېښودل.', 'هغوی دا شیان د خېمې چخه راوویستل، یوشع او تولو اسراییلیانو ته یې ورورل او د چشتن په حضور کې یې کېشودل.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Joshua_7_23.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237839, 1761237839),
(36864, 'Joshua 7:24', 'Joshua', 7, 24, 'بیا یوشع د اسراییلو د ټول قوم سره عخان، سپین زر، چپنه، د سرو زرو سیخ، د هغه زامن او لورګانې، پادې، خره او پسونه، د هغه خېمه او هرڅه یې چې درلودل د «مصیبت درې» ته یووړل.', 'بیا یوشع د اسراییلو د تول قوم سره عخان، سپین زر، چپنه، د سرو زرو سیخ، د هغه زامن او لورګانې، پادې، خره او پسونه، د هغه خېمه او هرچه یې چې درلودل د «مصیبت درې» ته یوورل.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Joshua_7_24.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237839, 1761237839),
(36865, 'Joshua 7:25', 'Joshua', 7, 25, 'یوشع عخان ته وویل: «تا ولې په مونږ باندې داسې مصیبت راوست؟ اوس به څښتن په تا باندې مصیبت راولي!» بیا ټول قوم عخان او د هغه کورنۍ په مرګ باندې سنګساره کړه. بیا یې د هغوی مړي د عخان د مال او جایداد سره یوځای وسوځول.', 'یوشع عخان ته وویل: «تا ولې په مونز باندې داسې مصیبت راوست؟ اوس به چشتن په تا باندې مصیبت راولی!» بیا تول قوم عخان او د هغه کورنی په مرګ باندې سنګساره کره. بیا یې د هغوی مری د عخان د مال او جایداد سره یوجای وسوجول.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Joshua_7_25.mp3', 'https://drive.google.com/uc?id=1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY&export=download', 1761237839, 1761237839),
(36866, 'Joshua 7:26', 'Joshua', 7, 26, 'په هغوی باندې یې د تیږو یوه لویه ډېرۍ جوړه کړه چې تر نن ورځې پورې هلته پاتې ده. بیا د څښتن سخت قهر سوړ شو. له دې امله دا ځای له هغه وخته راهیسې د مصیبت د درې په نوم یادیږي.', 'په هغوی باندې یې د تیزو یوه لویه دېری جوره کره چې تر نن ورجې پورې هلته پاتې ده. بیا د چشتن سخت قهر سور شو. له دې امله دا جای له هغه وخته راهیسې د مصیبت د درې په نوم یادیزی.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Joshua_7_26.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237839, 1761237839),
(36867, 'Proverbs 4:1', 'Proverbs', 4, 1, 'ای زما زامنو! د خپل پلار نصیحت ته غوږ ونیسئ او هغه ته پام وکړئ چې عقل زده کړئ', 'ای زما زامنو! د خپل پلار نصیحت ته غوز ونیسی او هغه ته پام وکری چې عقل زده کری', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/proverbs004_verse_001.mp3', 'https://pashto-bible-search.vercel.app/api/audio-proxy?id=11Atj4yfrM3Dgl7QHdLtbCo-ykq8mJ4wo&export=download', 1761237839, 1761237839),
(36868, 'Proverbs 4:2', 'Proverbs', 4, 2, 'ځکه چې زه تاسو ته ښه تعلیم درکوم نو زما ښوونه او روزنه مه هېروئ.', 'جکه چې زه تاسو ته شه تعلیم درکوم نو زما شوونه او روزنه مه هېروی.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/proverbs004_verse_002.mp3', 'https://drive.google.com/file/d/1rGzkES0csEYiA2NYhoP0fbtAF8yA-nj0/preview', 1761237839, 1761237839),
(36869, 'Proverbs 4:3', 'Proverbs', 4, 3, 'کله چې زه د خپل پلار ځوان زوی وم او د خپلې مور په نظر یوازېنی او نازولی ماشوم وم', 'کله چې زه د خپل پلار جوان زوی وم او د خپلې مور په نظر یوازېنی او نازولی ماشوم وم', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/proverbs004_verse_003.mp3', 'https://drive.google.com/file/d/1UXUH5n2lCHCf22trx9n5kA7aw8II9mr8/preview', 1761237839, 1761237839),
(36870, 'Proverbs 4:4', 'Proverbs', 4, 4, 'پلار مې ماته لارښوونه کوله او راته ویل به یې: «زما خبرې دې په خپل زړه کې ټینګې وساته او زما په حکمونو عمل کوه چې نېکمرغه ژوند ولرې.', 'پلار مې ماته لارشوونه کوله او راته ویل به یې: «زما خبرې دې په خپل زره کې تینګې وساته او زما په حکمونو عمل کوه چې نېکمرغه ژوند ولرې.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/proverbs004_verse_004.mp3', 'https://pashto-bible-search.vercel.app/api/audio-proxy?id=1qEEY5CIo1m0DGbHYJGihtk0zdCgi10YW&export=download', 1761237839, 1761237839),
(36871, 'Proverbs 4:5', 'Proverbs', 4, 5, 'حکمت حاصل کړه، عقل پیدا کړه زما کلام مه هېروه او مخ ترې مه اړوه.', 'حکمت حاصل کره، عقل پیدا کره زما کلام مه هېروه او مخ ترې مه اروه.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/proverbs004_verse_005.mp3', 'https://drive.google.com/file/d/1oEv-ScKuQIqrGCI2G4DD2jXyBvJ7cibQ/preview', 1761237839, 1761237839),
(36872, 'Proverbs 4:6', 'Proverbs', 4, 6, 'حکمت له لاسه مه ورکوه نو ستا ساتنه به کوي او ورسره مینه کوه نو ستا حفاظت به کوي.', 'حکمت له لاسه مه ورکوه نو ستا ساتنه به کوی او ورسره مینه کوه نو ستا حفاظت به کوی.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/proverbs004_verse_006.mp3', 'https://drive.google.com/file/d/18Jhm-ir6PaQ52OaVM7KO6tCYLgUkWoIn/preview', 1761237839, 1761237839),
(36873, 'Proverbs 4:7', 'Proverbs', 4, 7, 'حکمت تر ټولو لوړ مقام لري نو حاصل یې کړه او د خپلې ټولې شتمنۍ په بیه عقل تر‌لاسه کړه!', 'حکمت تر تولو لور مقام لری نو حاصل یې کره او د خپلې تولې شتمنی په بیه عقل تر‌لاسه کره!', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/proverbs004_verse_007.mp3', 'https://drive.google.com/file/d/1fRbfEmzvD_BoopNZYfFp6DNL_lSYiZpt/preview', 1761237839, 1761237839),
(36874, 'Proverbs 4:8', 'Proverbs', 4, 8, 'په درنه سترګه ورته ګوره نو تا به سرلوړی کړي. که ورته غاړه ورکړې نو ته به عزتمن شې.', 'په درنه سترګه ورته ګوره نو تا به سرلوری کری. که ورته غاره ورکرې نو ته به عزتمن شې.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/proverbs004_verse_008.mp3', 'https://pashto-bible-search.vercel.app/api/audio-proxy?id=1JtT-XtQgt1js0X9X8qCSEYJf59P6z6UU&export=download', 1761237839, 1761237839),
(36875, 'Proverbs 4:9', 'Proverbs', 4, 9, 'ستا په سر به د افتخار شمله کېږدي او ښکلی تاج به در په سر کړي.»', 'ستا په سر به د افتخار شمله کېزدی او شکلی تاج به در په سر کری.»', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/proverbs004_verse_009.mp3', 'https://pashto-bible-search.vercel.app/api/audio-proxy?id=1Cel1hgV5cFF61a1uSttq2N_cHGN643rY&export=download', 1761237839, 1761237839),
(36876, 'Proverbs 4:10', 'Proverbs', 4, 10, 'نو ای زما زویه! ماته غوږ شه او خبرې مې ومنه نو په دې کار سره به دې عمر ډېر شي.', 'نو ای زما زویه! ماته غوز شه او خبرې مې ومنه نو په دې کار سره به دې عمر دېر شی.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/proverbs004_verse_010.mp3', 'https://pashto-bible-search.vercel.app/api/audio-proxy?id=1hizEzgIs1cNi9L8Zd5PSkUg8YIuADyQR&export=download', 1761237839, 1761237839),
(36877, 'Proverbs 4:11', 'Proverbs', 4, 11, 'تاته مې د حکمت لار وښودله او ته مې د صداقت په لارو روان کړې.', 'تاته مې د حکمت لار وشودله او ته مې د صداقت په لارو روان کرې.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/proverbs004_verse_011.mp3', 'https://drive.google.com/file/d/16DbDB9J-AEU0Kk5tdwGq5pracWARscAs/preview', 1761237839, 1761237839),
(36878, 'Proverbs 4:12', 'Proverbs', 4, 12, 'په ګرځېدو کې به دې پښه په څه شي نه لګیږي او په منډه وهلو کې به نه ښویېږې.', 'په ګرجېدو کې به دې پشه په چه شی نه لګیزی او په منده وهلو کې به نه شویېزې.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/proverbs004_verse_012.mp3', 'https://drive.google.com/file/d/1L3eH2qhZJ_C-yqhgexjgKapl1eBx0bzI/preview', 1761237839, 1761237839),
(36879, 'Proverbs 4:13', 'Proverbs', 4, 13, 'نصیحت ته مې غاړه کېږده او له لاسه یې مه ورکوه ټینګه ساتنه یې وکړه ځکه چې هغه ستا ژوند دی.', 'نصیحت ته مې غاره کېزده او له لاسه یې مه ورکوه تینګه ساتنه یې وکره جکه چې هغه ستا ژوند دی.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/proverbs004_verse_013.mp3', 'https://pashto-bible-search.vercel.app/api/audio-proxy?id=1VtmSQDHEPWGWflZp34hR4I3KWL4y-PLd&export=download', 1761237839, 1761237839),
(36880, 'Proverbs 4:14', 'Proverbs', 4, 14, 'د بدکارانو په لاره قدم مه ږده او د شر اچوونکو په لاره تلل مه کوه.', 'د بدکارانو په لاره قدم مه زده او د شر اچوونکو په لاره تلل مه کوه.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/proverbs004_verse_014.mp3', 'https://drive.google.com/file/d/1vZ0yuwsKou715Zj1foEi_MsfqZQR65qo/preview', 1761237839, 1761237839),
(36881, 'Proverbs 4:15', 'Proverbs', 4, 15, 'ځان ترې وساته او پرې مه ځه مخ ترې واړوه او ورڅخه تېر شه.', 'جان ترې وساته او پرې مه جه مخ ترې واروه او ورچخه تېر شه.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/proverbs004_verse_015.mp3', 'https://drive.google.com/file/d/1mNx7rErMbb6F1TNTHWAPTiwlmDR1QwBw/preview', 1761237839, 1761237839),
(36882, 'Proverbs 4:16', 'Proverbs', 4, 16, 'ځکه دوی ته خوب نه ورځي چې چاته یې زیان نه وي رسولی او تر هغې نه ویده کیږي ترڅو چې بل یې نه وي غورځولی.', 'جکه دوی ته خوب نه ورجی چې چاته یې زیان نه وی رسولی او تر هغې نه ویده کیزی ترچو چې بل یې نه وی غورجولی.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/proverbs004_verse_016.mp3', 'https://pashto-bible-search.vercel.app/api/audio-proxy?id=1MABkP1DSOLV2JGa-6wp2aYg7aywZwAnc&export=download', 1761237839, 1761237839),
(36883, 'Proverbs 4:17', 'Proverbs', 4, 17, 'شرارت ورته د ډوډۍ په شان وي چې تل یې خوري او ظلم ورته د شرابو په څېر دی چې تل یې څښي.', 'شرارت ورته د دودی په شان وی چې تل یې خوری او ظلم ورته د شرابو په چېر دی چې تل یې چشی.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/proverbs004_verse_017.mp3', 'https://pashto-bible-search.vercel.app/api/audio-proxy?id=1krfn6rt0ndoki5_mCehafJ3QgOlQ8Pw0&export=download', 1761237839, 1761237839),
(36884, 'Proverbs 4:18', 'Proverbs', 4, 18, 'خو د نېکانو لار د سباوون د رڼا په شان ده چې روښنایي یې زیاتیږي ترڅو د غرمې رڼا لګیږي.', 'خو د نېکانو لار د سباوون د رنا په شان ده چې روشنایی یې زیاتیزی ترچو د غرمې رنا لګیزی.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/proverbs004_verse_018.mp3', 'https://pashto-bible-search.vercel.app/api/audio-proxy?id=1qdfKdq1EXQ7T__TCLS0fBBMi1Un6YSLF&export=download', 1761237839, 1761237839),
